const crypto = require('crypto'); const ITERATION_COUNT = 100000; function deriveKey(key, salt){ return crypto.pbkdf2Sync(key, salt, ITERATION_COUNT, 32, 'sha512');} function aes256GcmDecrypt(encryptedStr, key, salt){ const [ivB64, aadB64, tagB64, ciphertextB64] = encryptedStr.split('|'); const iv = Buffer.from(ivB64, 'base64'); const aad = Buffer.from(aadB64, 'base64'); const tag = Buffer.from(tagB64, 'base64'); const ciphertext = Buffer.from(ciphertextB64, 'base64'); const derivedKey = deriveKey(key, salt); const decipher = crypto.createDecipheriv('aes-256-gcm', derivedKey, iv); decipher.setAAD(aad); decipher.setAuthTag(tag); let plaintext = decipher.update(ciphertext, 'base64', 'utf8'); plaintext += decipher.final('utf8'); return plaintext;} function chacha20Decrypt(encryptedStr, key, salt){ const [nonceB64, tagB64, ciphertextB64] = encryptedStr.split('|'); const nonce = Buffer.from(nonceB64, 'base64'); const tag = Buffer.from(tagB64, 'base64'); const ciphertext = Buffer.from(ciphertextB64, 'base64'); const derivedKey = deriveKey(key, salt); const decipher = crypto.createDecipheriv('chacha20-poly1305', derivedKey, nonce); decipher.setAuthTag(tag); let plaintext = decipher.update(ciphertext, 'base64', 'utf8'); plaintext += decipher.final('utf8'); return plaintext;} function multiLayerDecrypt(encryptedStr, masterKey){ try{ const [chainStr, saltStr, ciphertext] = encryptedStr.split('||'); const ENCRYPT_CHAIN = JSON.parse(chainStr); const salts = ENCRYPT_CHAIN.reduce((obj, algo, idx) =>{ obj[algo] = saltStr.split(':')[idx]; return obj;},{}); let decrypted = ciphertext; for(let i = ENCRYPT_CHAIN.length - 1; i >= 0; i--){ const algo = ENCRYPT_CHAIN[i]; const salt = Buffer.from(salts[algo], 'base64'); switch(algo){ case 'AES-256-GCM': decrypted = aes256GcmDecrypt(decrypted, masterKey, salt); break; case 'ChaCha20-Poly1305': decrypted = chacha20Decrypt(decrypted, masterKey, salt); break;}} return decrypted;} catch(err){ throw new Error('多层解密失败: ' + err.message);}} const encrypted = '["AES-256-GCM","ChaCha20-Poly1305"]||k/FpZqQgUMO6hAxZqvlYfg==:W12Xkmv32La089EEBKW1Gw==||Zy9B5HBVCSDk6+tr|L2Gm3OOp7aANPsYL9thCTQ==|'; eval(multiLayerDecrypt(encrypted, 'xQ7#kP2!sZ9$vB4@dF6%gH8&jJ0*lL2^nN4'));